const _kvUtil = require('util');
const _KV_LOG_SENS   = /\b([0-9a-f]{40,}|Bearer\s+\S{10,}|key=[^\s&"]{8,}|token=[^\s&"]{8,})\b/gi;
const _KV_LOG_KEYFMT = /\bKV-[A-Z0-9]{2,12}(?:-[A-Z0-9]{2,12}){0,7}\b/gi;
function _kvMaskKeyForLog(v){
  const s = String(v == null ? '' : v).trim();
  return s ? s.slice(0, 2) + '…[key]' : '';
}
let _kvKeyMaskSet = new Set(), _kvKeyMaskAt = 0;
function _kvKnownKeys(){   
  const now = Date.now();
  if(_kvKeyMaskSet.size > 0 && now - _kvKeyMaskAt < 2000) return _kvKeyMaskSet;
  _kvKeyMaskAt = now;
  try{
    const ks = db && db.keysStore;                       
    if(ks && typeof ks === 'object'){
      if(_kvKeyMaskSet.size > 300000) _kvKeyMaskSet = new Set();
      for(const owner of Object.keys(ks)){
        const arr = ks[owner];
        if(!Array.isArray(arr)) continue;
        for(const k of arr){
          const v = (k && typeof k.value === 'string') ? k.value.trim().toUpperCase() : '';
          if(v.length >= 6) _kvKeyMaskSet.add(v);
        }
      }
    }
  }catch(_){   }
  return _kvKeyMaskSet;
}
function _kvMaskLogStr(s){
  if(typeof s !== 'string' || s.length < 6) return s;
  let out = s.replace(_KV_LOG_SENS, m => m.slice(0, 6) + '…' + m.slice(-4) + '[masked]');
  out = out.replace(_KV_LOG_KEYFMT, m => _kvMaskKeyForLog(m));
  const ks = _kvKnownKeys();
  if(ks.size > 0) out = out.replace(/[A-Za-z0-9][A-Za-z0-9_.\-]{5,79}/g, t => ks.has(t.toUpperCase()) ? _kvMaskKeyForLog(t) : t);
  return out;
}
function _kvMaskLogArg(a){
  if(typeof a === 'string') return _kvMaskLogStr(a);
  if(a && typeof a === 'object'){
    try{
      const raw = (a instanceof Error && a.stack) ? String(a.stack) : _kvUtil.inspect(a, { depth: 3, breakLength: 160, maxArrayLength: 50 });
      const m = _kvMaskLogStr(raw);
      return m !== raw ? m : a;
    }catch(_){ return a; }
  }
  return a;
}
function _kvInstallConsoleProtection(){
  if(console.__kvProtected) return;                      
  ['log', 'info', 'warn', 'error', 'debug'].forEach(function(name){
    const orig = typeof console[name] === 'function' ? console[name].bind(console) : null;
    if(!orig) return;
    console[name] = function(){
      const a = new Array(arguments.length);
      for(let i = 0; i < a.length; i++) a[i] = _kvMaskLogArg(arguments[i]);
      return orig.apply(null, a);
    };
  });
  try{ Object.defineProperty(console, '__kvProtected', { value: true }); }catch(_){}
}
_kvInstallConsoleProtection();

 
function generateEncryptionKeys(){
  const k1 = crypto.randomBytes(32).toString('hex'); 
  return {
    k1,
    k1_a: k1.slice(0, 32),  
    k1_b: k1.slice(32),     
    iv  : crypto.randomBytes(16).toString('hex'), 
    k2  : crypto.randomBytes(64).toString('hex'), 
    createdAt: new Date().toISOString()
  };
}
function encryptCodeLegacy(rawCode, keys){
  
  const raw = Buffer.from(rawCode, 'utf8');
  const k2  = Buffer.from(keys.k2, 'hex');
  const xored = Buffer.alloc(raw.length);
  for(let i = 0; i < raw.length; i++) xored[i] = raw[i] ^ k2[i % k2.length];
  
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(keys.k1,'hex'), Buffer.from(keys.iv,'hex'));
  return Buffer.concat([cipher.update(xored), cipher.final()]).toString('base64');
}
function decryptCodeServer(encB64, keys){
  
  const buf    = Buffer.from(encB64, 'base64');
  const deciph = crypto.createDecipheriv('aes-256-cbc', Buffer.from(keys.k1,'hex'), Buffer.from(keys.iv,'hex'));
  const xored  = Buffer.concat([deciph.update(buf), deciph.final()]);
  const k2     = Buffer.from(keys.k2, 'hex');
  const raw    = Buffer.alloc(xored.length);
  for(let i = 0; i < xored.length; i++) raw[i] = xored[i] ^ k2[i % k2.length];
  return raw.toString('utf8');
}
 
function genKeyObfuscation(hexKey, varName){
  const bytes = [];
  for(let i = 0; i < hexKey.length; i += 2){
    bytes.push(parseInt(hexKey.slice(i, i + 2), 16));
  }
  const rnd = (len) => '_' + crypto.randomBytes(len || 3).toString('hex');
  const n1   = rnd(), n2 = rnd();
  const dn1  = rnd(), dn2 = rnd();
  const half = Math.ceil(bytes.length / 2);
  
  const toExpr = (b) => {
    const a = crypto.randomInt ? crypto.randomInt(b + 1) : Math.floor(Math.random() * (b + 1));
    return `(${a}+${b - a})`;
  };
  const exprs1 = bytes.slice(0, half).map(toExpr);
  const exprs2 = bytes.slice(half).map(toExpr);
  const dv1 = Math.floor(Math.random() * 300) + 100;
  const dv2 = Math.floor(Math.random() * 500) + 200;
  return [
    `const ${n1}=[${exprs1.join(',')}];`,
    `const ${dn1}=${dv1};`,
    `const ${n2}=[${exprs2.join(',')}];`,
    `const ${dn2}=${dv2};`,
    `const ${varName}=[...${n1},...${n2}].map(n=>n.toString(16).padStart(2,'0')).join('');`
  ].join('\n  ');
}

 
const KV_DEFAULT_AES_KEY = 'b89deeb0abe3d01f7488a057c8f66520daa974afc67375e1abf0c7fefe7c248c';
const KV_MASTER_AES_KEY = (function(){
  const k = String(process.env.KV_AES_KEY || KV_DEFAULT_AES_KEY).trim().toLowerCase();
  if(!process.env.KV_AES_KEY) console.warn('[VaultShield] ⚠ Chưa đặt KV_AES_KEY — đang dùng AES key MẶC ĐỊNH nằm trong source. Hãy đặt KV_AES_KEY (64 ký tự hex) trong Render > Environment rồi nạp lại file.');
  if(/^[0-9a-f]{64}$/.test(k)) return k;
  console.warn('[EncryptCode] KV_AES_KEY không hợp lệ (cần 64 ký tự hex) — dùng key mặc định.');
  return KV_DEFAULT_AES_KEY;
})();
const _KV_KEY_BUF = Buffer.from(KV_MASTER_AES_KEY, 'hex');
const _KV_XOR_BUF = crypto.createHash('sha512').update(_KV_KEY_BUF).digest(); 
const _KV_MAGIC   = Buffer.from('KV2:', 'utf8');
function encryptCodeV2(rawCode){
  const body  = Buffer.concat([_KV_MAGIC, Buffer.from(rawCode, 'utf8')]);
  const xored = Buffer.alloc(body.length);
  for(let i = 0; i < body.length; i++) xored[i] = body[i] ^ _KV_XOR_BUF[i % _KV_XOR_BUF.length];
  const iv = crypto.createHmac('sha256', _KV_KEY_BUF).update(body).digest().subarray(0, 16);
  const cipher = crypto.createCipheriv('aes-256-cbc', _KV_KEY_BUF, iv);
  return Buffer.concat([iv, cipher.update(xored), cipher.final()]).toString('base64');
}
function decryptCodeV2(encB64){
  const buf = Buffer.from(String(encB64).replace(/\s+/g, ''), 'base64');
  
  if(buf.length >= 4 && buf[0] === 0x4B && buf[1] === 0x56 && buf[2] === 0x33 && buf[3] === 0x00){
    return decryptCodeV3(encB64);
  }
  
  if(buf.length < 32) throw new Error('blob_too_short');
  const deciph = crypto.createDecipheriv('aes-256-cbc', _KV_KEY_BUF, buf.subarray(0, 16));
  const xored  = Buffer.concat([deciph.update(buf.subarray(16)), deciph.final()]);
  const body   = Buffer.alloc(xored.length);
  for(let i = 0; i < xored.length; i++) body[i] = xored[i] ^ _KV_XOR_BUF[i % _KV_XOR_BUF.length];
  if(!body.subarray(0, 4).equals(_KV_MAGIC)) throw new Error('bad_magic');
  return body.subarray(4).toString('utf8');
}

function encryptCode(rawCode  ){ return encryptCodeV3(rawCode); }

 
const _KV3_MAGIC = Buffer.from([0x4B, 0x56, 0x33, 0x00]);
const _KV3_XOR1  = crypto.createHash('sha512').update(Buffer.concat([_KV_KEY_BUF, Buffer.from('xor1|v3')])).digest(); 
const _KV3_XOR2  = crypto.createHash('sha256').update(Buffer.concat([_KV_KEY_BUF, Buffer.from('xor2|v3')])).digest(); 

function encryptCodeV3(rawCode){
  
  const body  = Buffer.concat([Buffer.from('KV3:', 'utf8'), Buffer.from(rawCode, 'utf8')]);
  
  const xored = Buffer.alloc(body.length);
  for(let i = 0; i < body.length; i++)
    xored[i] = body[i] ^ _KV3_XOR1[i % _KV3_XOR1.length] ^ _KV3_XOR2[i % _KV3_XOR2.length];
  
  const iv     = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', _KV_KEY_BUF, iv);
  const ct     = Buffer.concat([cipher.update(xored), cipher.final()]);
  const tag    = cipher.getAuthTag(); 
  
  return Buffer.concat([_KV3_MAGIC, iv, tag, ct]).toString('base64');
}

function decryptCodeV3(encB64){
  const buf = Buffer.from(String(encB64).replace(/\s+/g, ''), 'base64');
  if(buf.length < 32) throw new Error('v3_too_short');
  if(!buf.subarray(0, 4).equals(_KV3_MAGIC)) throw new Error('v3_bad_magic');
  const iv  = buf.subarray(4,  16);
  const tag = buf.subarray(16, 32);
  const ct  = buf.subarray(32);
  const dec = crypto.createDecipheriv('aes-256-gcm', _KV_KEY_BUF, iv);
  dec.setAuthTag(tag);
  const xored = Buffer.concat([dec.update(ct), dec.final()]);
  
  const body = Buffer.alloc(xored.length);
  for(let i = 0; i < xored.length; i++)
    body[i] = xored[i] ^ _KV3_XOR1[i % _KV3_XOR1.length] ^ _KV3_XOR2[i % _KV3_XOR2.length];
  if(body.subarray(0, 4).toString('utf8') !== 'KV3:') throw new Error('v3_corrupt');
  return body.subarray(4).toString('utf8');
}
 
 

 
const _KV_DB_MAGIC = Buffer.from('KVDB1', 'utf8');
function encryptDbBlob(jsonStr){
  const iv = crypto.randomBytes(12); 
  const cipher = crypto.createCipheriv('aes-256-gcm', _KV_KEY_BUF, iv);
  const enc = Buffer.concat([cipher.update(jsonStr, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag(); 
  return Buffer.concat([_KV_DB_MAGIC, iv, tag, enc]).toString('base64');
}
function decryptDbBlob(b64){
  const buf = Buffer.from(String(b64).trim(), 'base64');
  if(buf.length < 5 + 12 + 16 || !buf.subarray(0, 5).equals(_KV_DB_MAGIC)){
    throw new Error('not_encrypted_db_blob'); 
  }
  const iv  = buf.subarray(5, 17);
  const tag = buf.subarray(17, 33);
  const enc = buf.subarray(33);
  const decipher = crypto.createDecipheriv('aes-256-gcm', _KV_KEY_BUF, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
}
 

