const _kvOTPStore = new Map();

/* [FIX-REPLAY] nonce `c` của /api/g/otp chỉ dùng được MỘT lần (trước đây chỉ kiểm tra định dạng 32 hex → phát lại cùng request vẫn lấy được OTP mới) */
const KV_OTP_NONCE_TTL_MS = 10 * 60 * 1000, KV_OTP_NONCE_MAX = 100000;
const _kvOtpNonces = new Map();   // nonce → thời điểm hết hạn (chèn theo thứ tự thời gian)
function _kvOtpNonceUsed(nonce){   // true = đã dùng rồi (replay) · false = lần đầu, đã ghi nhận
  const now = Date.now();
  const e = _kvOtpNonces.get(nonce);
  if(e !== undefined){ if(e > now) return true; _kvOtpNonces.delete(nonce); }
  if(_kvOtpNonces.size >= KV_OTP_NONCE_MAX){ const o = _kvOtpNonces.keys().next().value; if(o !== undefined) _kvOtpNonces.delete(o); }
  _kvOtpNonces.set(nonce, now + KV_OTP_NONCE_TTL_MS);
  return false;
}
setInterval(() => { const now = Date.now(); for(const [k, exp] of _kvOtpNonces){ if(exp > now) break; _kvOtpNonces.delete(k); } }, 60000).unref();
/* [FIX-DUMPTRAP] môi trường dump → phát OTP mồi gắn cờ dumpTrap (giao trang bẫy ở /api/sc/) thay vì 403 ngay. KV_DUMP_TRAP=0 → từ chối 403 như cũ. */
const KV_DUMP_TRAP = process.env.KV_DUMP_TRAP !== '0';

setInterval(() => {
  const now = Date.now();
  for (const [k, v] of _kvOTPStore.entries()) {
    if (now > v.exp + 30000) _kvOTPStore.delete(k); 
  }
}, 15000);

 
function _kvOTPEncrypt(plaintext, keyHex) {
  const key  = Buffer.from((keyHex || KV_MASTER_AES_KEY).slice(0, 64), 'hex');
  const iv   = crypto.randomBytes(12);
  const ciph = crypto.createCipheriv('aes-256-gcm', key, iv);
  const enc  = Buffer.concat([ciph.update(Buffer.from(plaintext, 'utf8')), ciph.final()]);
  const tag  = ciph.getAuthTag();
  return Buffer.concat([iv, tag, enc]).toString('base64url');
}

 
function _kvGenOTP() {
  return crypto.randomBytes(32).toString('hex');
}

 
function _kvDetectPlatform(ua) {
  if (!ua) return 'unknown';
  const s = String(ua).toLowerCase();
  if (s.includes('android'))                                              return 'android';
  if (s.includes('iphone') || s.includes('ipad') || s.includes('ios'))  return 'ios';
  if (s.includes('violentmonkey') || s.includes('greasemonkey') ||
      s.includes('tampermonkey') || s.includes('userscript'))            return 'vm';
  return 'other';
}

 
function _kvCountPlatformDevices(keyObj) {
  if (!keyObj) return { android: 0, ios: 0, total: 0 };
  const all = [
    ...(keyObj.devices      || []),
    ...(keyObj.devices_lua  || []),
    ...(keyObj.devices_vm   || [])
  ];
  let android = 0, ios = 0;
  for (const d of all) {
    const s = (typeof d === 'string')
      ? d.toLowerCase()
      : [d.deviceName || '', d.ua || '', d.platform || ''].join(' ').toLowerCase();
    if (s.includes('android'))                                              android++;
    else if (s.includes('iphone') || s.includes('ipad') || s.includes('ios')) ios++;
  }
  return { android, ios, total: all.length };
}

 
function _kvDecryptSnippetContent(sn) {
  if (!sn) return null;
  
  if (sn.code && !sn.encrypted) return sn.code;
  
  if (sn.encrypted && sn.encrypted.cipher) {
    try {
      const buf = Buffer.from(sn.encrypted.cipher, 'base64url');
      const iv  = buf.slice(0, 12);
      const tag = buf.slice(12, 28);
      const enc = buf.slice(28);
      const key = Buffer.from(KV_MASTER_AES_KEY.slice(0, 64), 'hex');
      const dec = crypto.createDecipheriv('aes-256-gcm', key, iv);
      dec.setAuthTag(tag);
      return Buffer.concat([dec.update(enc), dec.final()]).toString('utf8');
    } catch (e) {
      console.error('[OTP-SC] Lỗi giải mã snippet:', e.message);
      return null;
    }
  }
  
  if (sn.code) return sn.code;
  return null;
}
 

 
