  "    <div class=\"modal-actions\">",
  "      <button class=\"btn\" id=\"btnOlmResetUsesConfirm\">Reset</button>",
  "      <button class=\"btn btn-ghost\" id=\"btnOlmResetUsesCancel\">Huỷ</button>",
