/* ============================================================================
   [KVX-CLIENT] LỚP BẢO MẬT PHÍA CLIENT CHO LOADER VIOLENTMONKEY (v1)
   ----------------------------------------------------------------------------
   Hàm dưới đây KHÔNG chạy trên server. Server chuyển nó thành chuỗi (toString) và nhúng vào script Violentmonkey
   do trang admin sinh ra (nút "Tạo Violentmonkey Script"). Nó chạy BÊN TRONG loader, dùng lại _AK / _SB / _devId /
   GM_xmlhttpRequest của loader, và chỉ "bọc" 2 lời gọi: POST /api/g/otp và GET /api/sc/<otp>.

   Giao thức (chi tiết ở khối [KVX] phía server):
     1) POST /api/x/h   { cp: khoá công khai ECDH P-256 tạm thời, n: nonce }
          ← { sid, sp: khoá công khai tạm của server, ch, b: số bit PoW, ttl, sig }
        • sig = HMAC(khoá-dẫn-xuất-từ-_AK, các trường) → loader xác thực SERVER thật (chặn MITM tráo khoá)
        • ECDH(cp, sp) → bí mật chung chỉ tồn tại trong RAM 2 đầu (không bao giờ đi qua mạng) → khoá MAC + khoá AES
        • PoW: tìm pn sao cho SHA-256(sid|ch|pn) có b bit 0 đứng đầu (bot hàng loạt tốn CPU, người dùng thật ~0.1s)
     2) Mỗi request được bảo vệ mang header  X-KVX: v1.<sid>.<pn>.<seq>.<mac>
        mac = HMAC(khoá MAC, method|url|sid|seq|sha256(body)) → chống giả mạo / phát lại / sửa request
     3) Phản hồi được server mã hoá AES-256-GCM (phong bì) bằng khoá của phiên → ai bắt gói / log proxy chỉ thấy bytes ngẫu nhiên
   Tương thích: điện thoại Android / iOS thật chạy bình thường (chỉ cần WebCrypto + GM_xmlhttpRequest như loader cũ).
   Server cũ / KVX tắt (404 ở /api/x/h) → tự quay về đường cũ, không hỏng.
   ============================================================================ */
function kvxClientFactory(AK, SB, GMX, devId){
  'use strict';
  var C = (typeof window !== 'undefined' && window.crypto) ? window.crypto : null;
  var SU = C && C.subtle;
  var ST = null, OFF = false;
  var TE = (typeof TextEncoder !== 'undefined') ? new TextEncoder() : null;
  var TD = (typeof TextDecoder !== 'undefined') ? new TextDecoder() : null;

  /* ---- SHA-256 / HMAC đồng bộ (thuần JS): dùng cho PoW + MAC + dẫn xuất khoá ---- */
  var K256 = new Uint32Array([
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ]);
  var W = new Uint32Array(64);
  function sha256(m){
    var H = new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);
    var l = m.length, nb = ((l + 9 + 63) >> 6) << 6;
    var p = new Uint8Array(nb); p.set(m); p[l] = 0x80;
    var dv = new DataView(p.buffer), bits = l * 8;
    dv.setUint32(nb - 8, Math.floor(bits / 4294967296), false);
    dv.setUint32(nb - 4, bits >>> 0, false);
    var i, o, a, b, s0, s1, A, B, Cc, D, E, F, G, Hh, S1, ch, t1, S0, mj, t2;
    for(o = 0; o < nb; o += 64){
      for(i = 0; i < 16; i++) W[i] = dv.getUint32(o + i * 4, false);
      for(i = 16; i < 64; i++){
        a = W[i - 15]; b = W[i - 2];
        s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
        s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
        W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
      }
      A = H[0]; B = H[1]; Cc = H[2]; D = H[3]; E = H[4]; F = H[5]; G = H[6]; Hh = H[7];
      for(i = 0; i < 64; i++){
        S1 = ((E >>> 6) | (E << 26)) ^ ((E >>> 11) | (E << 21)) ^ ((E >>> 25) | (E << 7));
        ch = (E & F) ^ (~E & G);
        t1 = (Hh + S1 + ch + K256[i] + W[i]) | 0;
        S0 = ((A >>> 2) | (A << 30)) ^ ((A >>> 13) | (A << 19)) ^ ((A >>> 22) | (A << 10));
        mj = (A & B) ^ (A & Cc) ^ (B & Cc);
        t2 = (S0 + mj) | 0;
        Hh = G; G = F; F = E; E = (D + t1) | 0; D = Cc; Cc = B; B = A; A = (t1 + t2) | 0;
      }
      H[0] = (H[0] + A) | 0; H[1] = (H[1] + B) | 0; H[2] = (H[2] + Cc) | 0; H[3] = (H[3] + D) | 0;
      H[4] = (H[4] + E) | 0; H[5] = (H[5] + F) | 0; H[6] = (H[6] + G) | 0; H[7] = (H[7] + Hh) | 0;
    }
    var out = new Uint8Array(32), od = new DataView(out.buffer);
    for(i = 0; i < 8; i++) od.setUint32(i * 4, H[i], false);
    return out;
  }
  function hmac(key, msg){
    var bs = 64, i;
    if(key.length > bs) key = sha256(key);
    var k = new Uint8Array(bs); k.set(key);
    var ip = new Uint8Array(bs + msg.length), op = new Uint8Array(bs + 32);
    for(i = 0; i < bs; i++){ ip[i] = k[i] ^ 0x36; op[i] = k[i] ^ 0x5c; }
    ip.set(msg, bs); op.set(sha256(ip), bs);
    return sha256(op);
  }
  function cat(a, b){ var o = new Uint8Array(a.length + b.length); o.set(a); o.set(b, a.length); return o; }
  function hkdf32(salt, ikm, info){ return hmac(hmac(salt, ikm), cat(info, [1])); }
  function hex(u){ var s = '', i; for(i = 0; i < u.length; i++) s += (u[i] < 16 ? '0' : '') + u[i].toString(16); return s; }
  function unhex(s){ var o = new Uint8Array(s.length >> 1), i; for(i = 0; i < o.length; i++) o[i] = parseInt(s.substr(i * 2, 2), 16); return o; }
  function b64u(u){
    var s = '', i;
    for(i = 0; i < u.length; i++) s += String.fromCharCode(u[i]);
    return btoa(s).split('+').join('-').split('/').join('_').split('=').join('');
  }
  function unb64u(s){
    s = String(s).split('-').join('+').split('_').join('/');
    while(s.length % 4) s += '=';
    var b = atob(s), o = new Uint8Array(b.length), i;
    for(i = 0; i < b.length; i++) o[i] = b.charCodeAt(i);
    return o;
  }
  function lz(u){
    var n = 0, i, b;
    for(i = 0; i < u.length; i++){
      b = u[i];
      if(b === 0){ n += 8; continue; }
      while(!(b & 0x80)){ n++; b = (b << 1) & 0xff; }
      break;
    }
    return n;
  }
  function tick(){ return new Promise(function(r){ setTimeout(r, 0); }); }

  /* ---- PoW: SHA-256(sid|ch|pn) phải có >= bits bit 0 đứng đầu ---- */
  async function solvePow(sid, ch, bits){
    if(!(bits > 0)) return '-';
    var pre = TE.encode(sid + '|' + ch + '|'), buf = new Uint8Array(pre.length + 12);
    buf.set(pre);
    var n = 0, d, t, k, len;
    for(;;){
      t = String(n); len = pre.length;
      for(k = 0; k < t.length; k++) buf[len++] = t.charCodeAt(k);
      if(lz(sha256(buf.subarray(0, len))) >= bits) return t;
      n++;
      if((n & 4095) === 0) await tick();
      if(n > 6000000) throw new Error('pow_fail');
    }
  }

  /* ---- Dấu hiệu công cụ tự động hoá (CHỈ marker đặc trưng của framework — không dùng heuristic dễ báo nhầm trên điện thoại) ---- */
  function envScore(){
    var s = 0, i, w, d, dk;
    try{ if(navigator.webdriver === true) s += 3; }catch(e){}
    try{
      w = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;
      d = (typeof document !== 'undefined') ? document : null;
      var nm = ['__playwright','__pwInitScripts','__pw_manual','__PW_inspect','_phantom','__phantomas','callPhantom','__nightmare',
        'domAutomation','domAutomationController','__selenium_unwrapped','__webdriver_evaluate','__driver_evaluate',
        '__webdriver_script_function','__webdriver_script_func','__webdriver_script_fn','__fxdriver_evaluate',
        '__fxdriver_unwrapped','_Selenium_IDE_Recorder','_selenium','calledSelenium','__lastWatirAlert','__lastWatirConfirm',
        '__lastWatirPrompt','$chrome_asyncScriptInfo','__$webdriverAsyncExecutor'];
      for(i = 0; i < nm.length; i++){
        if(w[nm[i]] !== undefined || (d && d[nm[i]] !== undefined)){ s += 3; break; }
      }
      if(d){
        dk = Object.keys(d);
        for(i = 0; i < dk.length; i++){
          if(/^[$]?cdc_/.test(dk[i]) || /^__(webdriver|selenium|driver)/.test(dk[i])){ s += 3; break; }
        }
      }
    }catch(e){}
    return s > 9 ? 9 : s;
  }

  function http(method, url, headers, data, tmo){
    return new Promise(function(res, rej){
      GMX({
        method: method, url: url, headers: headers, data: data, timeout: tmo || 30000,
        onload: function(r){ res(r); },
        onerror: function(e){ rej(e || new Error('network_error')); },
        ontimeout: function(){ rej(new Error('timeout')); }
      });
    });
  }

  /* ---- Bắt tay: ECDH P-256 tạm thời + xác thực server bằng _AK + PoW ---- */
  async function hello(){
    var kp = null, cp = null, tryExtractable = [false, true], i;
    for(i = 0; i < tryExtractable.length && !cp; i++){
      try{
        kp = await SU.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, tryExtractable[i], ['deriveBits']);
        cp = new Uint8Array(await SU.exportKey('raw', kp.publicKey));
      }catch(e){ cp = null; }
    }
    if(!cp) throw new Error('kvx_ecdh_unsupported');
    var cn = hex(C.getRandomValues(new Uint8Array(16)));
    var cpb = b64u(cp);
    var r = await http('POST', SB + '/api/x/h', { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' },
      JSON.stringify({ v: 1, cp: cpb, n: cn, d: devId(), es: envScore() }), 20000);
    if(r.status === 404) throw { legacy: true };
    var j = null;
    try{ j = JSON.parse(r.responseText); }catch(e){}
    if(r.status !== 200 || !j || !j.ok || !j.sid || !j.sp || !j.ch || !j.sig) throw { deny: true, status: r.status, text: r.responseText };
    var authKey = hkdf32(TE.encode('kvx-auth-v1'), unhex(AK), TE.encode('kvx-hello'));
    var want = b64u(hmac(authKey, TE.encode(['kvx-hello', j.sid, j.sp, j.ch, j.b, j.ttl, cpb, cn].join('|'))));
    var okSig = (want.length === String(j.sig).length), q, dif = 0;
    for(q = 0; q < want.length && q < String(j.sig).length; q++) dif |= want.charCodeAt(q) ^ String(j.sig).charCodeAt(q);
    if(!okSig || dif !== 0) throw { auth: true };
    var spk = await SU.importKey('raw', unb64u(j.sp), { name: 'ECDH', namedCurve: 'P-256' }, false, []);
    var shared = new Uint8Array(await SU.deriveBits({ name: 'ECDH', public: spk }, kp.privateKey, 256));
    var prk = hmac(TE.encode('kvx2|' + j.sid + '|' + cn + '|' + j.ch), shared);
    var kmac = hmac(prk, cat(TE.encode('kvx-mac'), [1]));
    var kenc = hmac(prk, cat(TE.encode('kvx-enc'), [1]));
    var ek = await SU.importKey('raw', kenc, 'AES-GCM', false, ['decrypt']);
    var pn = await solvePow(j.sid, j.ch, j.b | 0);
    return { sid: j.sid, kmac: kmac, ek: ek, pn: pn, n: 0, seq: 0, exp: Date.now() + Math.max(20000, (j.ttl | 0) - 15000) };
  }

  /* ---- Mở phong bì phản hồi (AES-256-GCM, AAD gắn với phiên + số thứ tự) ---- */
  async function open(st, seq, r){
    var j = null;
    try{ j = JSON.parse(r.responseText); }catch(e){}
    if(j && j.x === 1 && j.i && j.c){
      var pt = new Uint8Array(await SU.decrypt({
        name: 'AES-GCM', iv: unb64u(j.i), additionalData: TE.encode('kvx-res|' + st.sid + '|' + seq), tagLength: 128
      }, st.ek, unb64u(j.c)));
      var pl = (pt[0] << 8) | pt[1];
      var m = JSON.parse(TD.decode(pt.subarray(2, pt.length - pl)));
      return { status: m.s, responseText: m.b, responseHeaders: '', finalUrl: r.finalUrl, kvx: true };
    }
    return r;
  }

  async function call(o, retried){
    var fresh = false;
    if(!ST || Date.now() > ST.exp || ST.n >= 6){ ST = null; ST = await hello(); fresh = true; }
    var st = ST, u = String(o.url), p = u.slice(SB.length);
    var method = String(o.method || 'GET').toUpperCase();
    var body = (o.data == null) ? '' : String(o.data);
    var seq = ++st.seq; st.n++;
    var mac = b64u(hmac(st.kmac, TE.encode([method, p, st.sid, seq, hex(sha256(TE.encode(body)))].join('|'))));
    var hd = {}, k;
    if(o.headers) for(k in o.headers) hd[k] = o.headers[k];
    hd['X-KVX'] = ['v1', st.sid, st.pn, seq, mac].join('.');
    var r = await http(method, u, hd, o.data, o.timeout);
    var out = await open(st, seq, r);
    if(!out.kvx){
      ST = null;   /* lỗi thường (phiên mất / server khởi động lại) → bỏ phiên */
      if(!fresh && !retried && (r.status === 403 || r.status === 404 || r.status === 410)) return call(o, true);
    }
    return out;
  }

  return function(o){
    var u = String((o && o.url) || '');
    var p = (u.indexOf(SB) === 0) ? u.slice(SB.length) : '';
    var prot = p.indexOf('/api/g/otp') === 0 || p.indexOf('/api/sc/') === 0 || p.indexOf('/api/g/k') === 0;   // [KV-UPGRADE] bọc POST /api/g/k (giao code game) vào KVX phong bì
    if(!prot || OFF || !SU || !C || !TE || !TD || typeof C.getRandomValues !== 'function') return GMX(o);
    call(o, false).then(function(r){ if(o.onload) o.onload(r); }, function(e){
      if(e && e.legacy){ OFF = true; GMX(o); return; }
      if(e && e.deny){ if(o.onload) o.onload({ status: e.status, responseText: e.text }); return; }
      if(o.onerror) o.onerror({ error: (e && e.auth) ? 'kvx_auth' : String((e && e.message) || e) });
    });
  };
}
