const KV_GATE_TTL_MS = 20 * 1000;
const _KV_GATE_MATERIAL = crypto.createHmac('sha512',
  Buffer.concat([Buffer.from(String(process.env.KV_GATE_SECRET || KV_SESSION_SECRET)), crypto.randomBytes(32)])
).update('kvgate|v1|' + KV_MASTER_AES_KEY).digest();
const _KV_GATE_ENC = _KV_GATE_MATERIAL.subarray(0, 32);   
const _KV_GATE_MAC = _KV_GATE_MATERIAL.subarray(32, 64);  

function _kvGateAAD(ip){
  return crypto.createHash('sha256').update('kvgate-aad|' + String(ip || '')).digest();
}

function _kvGateFingerprint(licKey, expBuf, nonce){
  const inner = crypto.createHmac('sha256', _KV_GATE_MAC).update('kvgate-fp|').update(String(licKey)).digest();
  return crypto.createHmac('sha256', inner).update(expBuf).update(nonce).digest().subarray(0, 16);
}
function _kvGateIssue(licKey, ip){
  const t = Date.now() + KV_GATE_TTL_MS;
  const exp = Buffer.alloc(8);
  exp.writeUInt32BE(Math.floor(t / 4294967296), 0);
  exp.writeUInt32BE(t >>> 0, 4);
  const nonce = crypto.randomBytes(8);
  const plain = Buffer.concat([_kvGateFingerprint(licKey, exp, nonce), exp, nonce]); 
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', _KV_GATE_ENC, iv);
  c.setAAD(_kvGateAAD(ip));
  const ct = Buffer.concat([c.update(plain), c.final()]);
  return Buffer.concat([iv, c.getAuthTag(), ct]); 
}
function _kvGateVerify(ticket, licKey, ip){
  try{
    if(!Buffer.isBuffer(ticket) || ticket.length !== 60) return false;
    const d = crypto.createDecipheriv('aes-256-gcm', _KV_GATE_ENC, ticket.subarray(0, 12));
    d.setAAD(_kvGateAAD(ip));
    d.setAuthTag(ticket.subarray(12, 28));
    const plain = Buffer.concat([d.update(ticket.subarray(28)), d.final()]); 
    if(plain.length !== 32) return false;
    const fp = plain.subarray(0, 16), exp = plain.subarray(16, 24), nonce = plain.subarray(24, 32);
    const expMs = exp.readUInt32BE(0) * 4294967296 + exp.readUInt32BE(4);
    if(expMs < Date.now()) return false;
    if(!crypto.timingSafeEqual(fp, _kvGateFingerprint(licKey, exp, nonce))) return false;
    return sfVerifyKey(licKey).valid === true; 
  }catch(_){ return false; }
}
 
