function _kvIPEscalated(ip){ return !!ip && (db.blockedIPs || []).some(b => b && b.ip === ip && !_kvIsAutoBlock(b)); }   // [FIX-IPBAN] chỉ IP admin khoá tay
function _kvStrike(scope, ip, limit, windowMs, banMs){
  if(_kvIsTrustedIP(ip)) return false;   // [FIX-IPBAN] IP đã xác thực key thành công → không tính vi phạm / không khoá
  const key = scope + ':' + ip, now = Date.now();
  let r = _kvStrikes.get(key);
  if(!r){ r = { hits: [], bannedUntil: 0 }; _kvStrikes.set(key, r); }
  if(r.bannedUntil > now) return true;
  r.hits = r.hits.filter(t => now - t < windowMs);
  r.hits.push(now);
  if(r.hits.length >= limit){
    
    const strikes = _kvIPThreatBump(ip);
    const mult = Math.min(64, Math.pow(2, Math.max(0, strikes - 1)));
    const dur = Math.min(banMs * mult, Math.max(banMs, KV_IP_AUTOBAN_MAX_MS));   // [FIX-IPBAN] chặn leo thang (trước: tới 7 ngày) — giữ nguyên thời gian cơ bản của từng điểm gọi
    r.bannedUntil = now + dur; r.hits = [];
    console.warn(`[VaultShield] Khoá tạm ${Math.round(dur / 60000)} phút (${scope}, vi phạm thứ ${strikes}) — IP ${ip}`);
    return true;
  }
  return false;
}
function _kvBanned(scope, ip){
  if(_kvIPEscalated(ip)) return true;                        // IP do admin khoá TAY → luôn chặn
  if(_kvIsTrustedIP(ip)) return false;                       // [FIX-IPBAN] IP vừa xác thực key thành công → không bị khoá tự động
  if(_kveIPBanned(ip) || _kvIPAutoBanned(ip)) return true;   
  const r = _kvStrikes.get(scope + ':' + ip);
  return !!(r && r.bannedUntil > Date.now());
}
setInterval(()=>{
  const now = Date.now();
  for(const [k, r] of _kvStrikes.entries()){
    const last = r.hits.length ? r.hits[r.hits.length - 1] : 0;
    if(r.bannedUntil < now && now - last > 15 * 60 * 1000) _kvStrikes.delete(k);
  }
}, 10 * 60 * 1000).unref();

 
