/* [SmartReal v1] CHẶN THÔNG MINH — công tắc chung. KV_SMART_REAL=0 → quay về đúng hành vi cũ ở mọi lớp bên dưới.
   Chi tiết cách hoạt động xem khối "SmartReal v1" ngay trước hàm kvsCheckDevice. */
const KVS_SMART_REAL = process.env.KV_SMART_REAL !== '0';

/* [Anti-CORS v6] Danh sách origin hợp lệ — chỉ cho phép trình duyệt từ các domain này.
   Đặt KV_ALLOWED_ORIGINS trong env: "https://olm.vn,https://www.olm.vn" (phân cách bằng dấu phẩy).
   Nếu không đặt → chỉ cho phép olm.vn + localhost. Wildcard (*) bị loại bỏ trên /api/g/*. */
const _KVS_ALLOWED_ORIGINS = (function(){
  const raw = String(process.env.KV_ALLOWED_ORIGINS || '').trim();
  const defaults = ['https://olm.vn', 'https://www.olm.vn'];
  if(!raw) return defaults;
  return [...new Set([...raw.split(',').map(s => s.trim()).filter(Boolean), ...defaults])];
})();

/* Trả về Access-Control-Allow-Origin phù hợp với request:
   - Nếu Origin của request nằm trong whitelist → reflect đúng origin đó (tốt hơn *)
   - Nếu không nằm trong whitelist → trả về origin đầu tiên trong list (null-origin sẽ bị browser block)
   - Dùng cho /api/g/* — các endpoint công khai khác vẫn có thể dùng * nếu cần */
function _kvCorsOrigin(req){
  const origin = String(req.headers['origin'] || '').trim();
  if(!origin) return _KVS_ALLOWED_ORIGINS[0];
  // Extension URL (moz-extension://, chrome-extension://) → cho phép (Violentmonkey chạy từ extension)
  if(/^(moz|chrome|safari-web)-extension:\/\//i.test(origin)) return origin;
  if(_KVS_ALLOWED_ORIGINS.some(o => o === origin)) return origin;
  // Origin không hợp lệ → trả về domain chính (browser sẽ block cross-origin response)
  return _KVS_ALLOWED_ORIGINS[0];
}

/* [Fix-Error-Enum v6] Chuẩn hóa error response cho /api/g/k và /api/g/d — không lộ lý do chi tiết.
   Attacker dùng error code phân biệt (key_invalid / no_script / device_pending) để dò tuần tự.
   Hàm này collapse tất cả về 'denied' + delay ngẫu nhiên để làm chậm enumeration. */
async function _kvSafeError(res, status, _internalReason, ref){
  await new Promise(r => setTimeout(r, 180 + Math.floor(Math.random() * 420)));
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Robots-Tag': 'noindex, nofollow'
  });
  // Luôn trả 'denied' — không phân biệt key sai / thiết bị chờ / snippet không tồn tại
  res.end(JSON.stringify({ ok: false, error: 'denied', ref: ref || null }));
}
/* GPU của ĐIỆN THOẠI / TABLET thật (Adreno, Mali, Immortalis, Xclipse, PowerVR, Apple GPU…) — Immortalis/Xclipse là chip flagship mới, trước đây không có trong whitelist */
const KVS_GPU_MOBILE_RE = /(adreno|\bmali\b|immortalis|xclipse|powervr|videocore|apple gpu|apple a\d{1,2}|a\d{1,2} bionic)/i;
const _ANTI_SCRIPT_BOT_UA = /^(curl[\/\s]|wget[\/\s]|python[-\/ ]|python[23]|go-http-client|node-fetch|node\.js|axios[\/\s]|got[\/\s]|undici|httpie|java\/|ruby\/|php\/|perl\/|libwww|okhttp|pycurl|scrapy|httpx|mechanize|aiohttp|requests\/|unirest|retrofit|jsdom|cheerio|playwright|puppeteer\/|selenium|cypress\/|phantomjs|headlesschrome|headless\s|apachebench|ab\/|vegeta|k6\/|locust|httpclient|sahi\/|jmeter|burpsuite|burp\/|owasp|zap\/|mitmproxy|fiddler|postman|insomnia|httprunner|grequests|urllib|httplib|nmap|masscan|zgrab|rustscan|nuclei|gobuster|dirbuster|nikto|sqlmap|whatweb|wfuzz|ffuf|httpkit|keyvault.extractor|kve\/|kvextract)/i;

 
const _ANTI_SCRIPT_STRICT_UA = /^(curl[\/\s]|wget[\/\s]|python[-\/]|python\d|go-http-client|node-fetch|axios[\/\s]|got[\/\s]|undici|httpie|pycurl|scrapy|httpx|aiohttp|playwright|puppeteer|selenium|phantomjs|headless|burp|mitmproxy|fiddler|keyvault|kve\/|kvextract|postman|insomnia|nikto|sqlmap|nuclei|ffuf)/i;

 
const _KVE_PROBE_HEADERS = [
  'x-kve-probe', 'x-kv-extract', 'x-extractor', 'x-script-dump',
  'x-bypass-kv', 'x-tamper-hook', 'x-keyvault', 'x-dump-js'
];

 
const _kvExtractorIPs = new Map();
const _KVE_IP_BAN_MS  = 30 * 60 * 1000;

/* [Anti-Replay v6] Store nonce đã dùng trong /api/g/k — TTL 5 phút (khớp session TTL).
   Chặn replay attack: gửi lại cùng request với nonce cũ không cho kết quả mới.
   Key = nonceHex:sidPrefix, Value = expiry timestamp. */
const _kvNonceStore = new Map();
setInterval(()=>{
  const now = Date.now();
  for(const [k, exp] of _kvNonceStore.entries()) if(exp < now) _kvNonceStore.delete(k);
}, 3 * 60 * 1000);

/* [Anti-SEC-Dump v6] Mã hóa SEC trước khi nhúng vào stage 2 — thay vì hex plaintext,
   SEC được XOR với mask sinh từ sha256(sid + server_salt), rồi encode thành array số.
   Attacker đọc stage 2 chỉ thấy array số, không thấy hex SEC thô.
   Client trong stage 2 tự unXOR để recover SEC thực.
   Server salt thay đổi mỗi lần khởi động — dump tool không thể hardcode. */
const _KVG_SEC_SALT = crypto.randomBytes(16).toString('hex');  // mỗi lần restart = salt mới
function _kvgMaskSec(secBuf, sid){
  // XOR key: derive từ sid prefix (8 ký tự) — khớp với thuật toán phía client trong stage 2.
  // Không dùng _KVG_SEC_SALT trong XOR key (client không biết salt) — salt chỉ dùng cho log/audit.
  // Mục tiêu: SEC không còn là hex thô trong JSON, đủ để tool dump không đọc được SEC trực tiếp.
  const sidBytes = Buffer.from(sid.slice(0, 8) || 'xxxxxxxx', 'utf8');
  const mask = Buffer.alloc(32, 0);
  for(let i = 0; i < secBuf.length; i++) mask[i % 32] ^= sidBytes[i % sidBytes.length];
  const out = [];
  for(let i = 0; i < secBuf.length; i++) out.push(secBuf[i] ^ mask[i % 32]);
  return out;  // array số [0-255] — không còn là hex string plaintext
}

function _kveMarkIP(ip){ if(ip && !_kvIsTrustedIP(ip)){ _kvExtractorIPs.set(ip, Date.now() + _KVE_IP_BAN_MS); _kvIPThreatBump(ip); } }   // [FIX-IPBAN] không đánh dấu IP đã xác thực key thành công   
function _kveIPBanned(ip){
  if(!ip) return false;
  if(_kvIsTrustedIP(ip)) return false;   // [FIX-IPBAN]
  const t = _kvExtractorIPs.get(ip);
  if(!t) return false;
  if(t < Date.now()){ _kvExtractorIPs.delete(ip); return false; }
  return true;
}
setInterval(()=>{ const now = Date.now(); for(const [k,v] of _kvExtractorIPs.entries()) if(v < now) _kvExtractorIPs.delete(k); }, 15 * 60 * 1000);

 
_kvInstallConsoleProtection();

 
function _kvRefTag(){ return 'ref-' + crypto.randomBytes(6).toString('hex'); }

 
function _kvAntiScriptCheck(req, strict){
  const ua  = String(req.headers['user-agent'] || '').trim();
  const ip  = getClientIP(req);

  
  if(_kveIPBanned(ip)) return { block: true, reason: 'kve_ip_memory' };

  
  for(const h of _KVE_PROBE_HEADERS){
    if(req.headers[h] !== undefined){ _kveMarkIP(ip); return { block: true, reason: 'kve_probe:' + h }; }
  }

  
  const acc = String(req.headers['accept'] || '');
  if(/application\/javascript/i.test(acc) && !req.headers['sec-fetch-dest']){
    return { block: true, reason: 'accept_js_no_dest' };
  }

  

  
  const botRx = strict ? _ANTI_SCRIPT_STRICT_UA : _ANTI_SCRIPT_BOT_UA;
  if(!ua || botRx.test(ua)){ _kveMarkIP(ip); return { block: true, reason: 'bot_ua' }; }

  
  const hasBrowserMark = /mozilla|gecko|webkit|chrome|safari|firefox/i.test(ua);
  const sfm  = req.headers['sec-fetch-mode']  || '';
  const sfst = req.headers['sec-fetch-site']  || '';
  const sfdt = req.headers['sec-fetch-dest']  || '';
  const chUa = req.headers['sec-ch-ua']       || req.headers['sec-ch-ua-platform'] || '';
  const accL = req.headers['accept-language'] || '';

  if(strict){
    
    if(!hasBrowserMark && !sfm && !sfst && !chUa && !accL && !(KVS_SMART_REAL && /(cfnetwork|darwin\/)/i.test(ua))){   // [SmartReal v1] iOS native (CFNetwork/Darwin) không có token trình duyệt / Accept-Language
      return { block: true, reason: 'no_browser_signal' };
    }
    
    const accStr = String(req.headers['accept'] || '');
    if(accStr === '*/*' && !accL && !req.headers['cookie'] && !sfm && !(KVS_SMART_REAL && /(cfnetwork|darwin\/)/i.test(ua))){   // [SmartReal v1] iOS native (CFNetwork/Darwin) không gửi Accept-Language / sec-fetch
      return { block: true, reason: 'minimal_headers' };
    }
    
    if(sfdt === 'script' && sfm && sfm !== 'no-cors' && sfm !== 'cors'){
      return { block: true, reason: 'abnormal_fetch_mode' };
    }
  }

  
  
  if(!strict){
    const origin = String(req.headers['origin'] || '');
    const referer = String(req.headers['referer'] || '');
    const hasCookie = !!req.headers['cookie'];
    
    if(!hasBrowserMark && !accL && !hasCookie && !origin && !referer && !(KVS_SMART_REAL && /(cfnetwork|darwin\/)/i.test(ua))){   // [SmartReal v1] như trên
      return { block: true, reason: 'no_browser_context' };
    }
  }

  return { block: false, reason: '' };
}

 
function _kvAntiScriptGuard(req, res, strict){
  const chk = _kvAntiScriptCheck(req, strict);
  if(chk.block){
    const ip = getClientIP(req);
    
    if(/kve_probe|kve_ip|accept_js|bot_ua/i.test(chk.reason)) _kveMarkIP(ip);
    
    if(!isRateLimited('anti-script-log', ip, 3, 60000)){
      console.warn('[AntiScript v3] Chặn IP=' + ip + ' ' + (req._kvRef || '') + ' r=' + chk.reason.slice(0,30) + ' ua=' + String(req.headers['user-agent']||'').slice(0,40));
    }
    
    _kvStrike('enum', ip, 25, 5 * 60 * 1000, 15 * 60 * 1000);
    
    _kvDeny(res, 404, 'not_found');
    return false;
  }
  return true;
}

 
function _kvIsProtectedScript(pathname){
  let param = '';
  try{ param = path.basename(decodeURIComponent(pathname.slice('/raw/'.length))).trim(); }catch(_){ return true; }
  if(!param) return false;
  const lower = param.toLowerCase();
  const noExt = lower.replace(/\.[^.]+$/, '');
  const all = (db.codeSnippets || []).concat(Object.values(_defaultSnippetMap).filter(d => !(db.codeSnippets || []).some(x => x.id === d.id)));
  for(const s of all){
    if(!s) continue;
    const dn = String(s.diskFilename || '').toLowerCase();
    const nm = String(s.name || '').toLowerCase();
    const hit = dn === lower || dn.replace(/\.[^.]+$/, '') === noExt || nm.replace(/\.[^.]+$/, '') === noExt || s.id === param;
    if(hit && String(s.language || 'javascript') !== 'lua') return true;
  }
  try{
    const dir = fs.readdirSync(SCRIPT_DIR);
    for(const f of dir){
      const fl = f.toLowerCase();
      if(fl === lower || fl.replace(/\.[^.]+$/, '') === lower){
        const fd = fs.openSync(path.join(SCRIPT_DIR, f), 'r');
        try{
          const buf = Buffer.alloc(4096);
          const n = fs.readSync(fd, buf, 0, 4096, 0);
          if(/==UserScript==/i.test(buf.slice(0, n).toString('utf8'))) return true;
        }finally{ fs.closeSync(fd); }
      }
    }
  }catch(_){}
  return false;
}

 
function kvShield(req, res, url, pathname, ip){
  if(KV_SHIELD_OFF) return true;
  const method = req.method;

  
  try{
    const dec = decodeURIComponent(String(req.url || '').split('?')[0]);
    if(dec.indexOf('\0') >= 0 || dec.indexOf('\\') >= 0 || dec.split('/').some(s => s === '..')){
      _kvDeny(res, 400, 'bad_request'); return false;
    }
  }catch(_){ _kvDeny(res, 400, 'bad_request'); return false; }
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');

  
  if(_KV_VAULT_ROUTES.some(rx => rx.test(pathname))){
    if(_kvAdminOK(req)) return true;
    _kvDeny(res, 401, 'admin_required', 'Cần đăng nhập admin để thao tác với kho code/file.');
    return false;
  }

  
  if(method === 'GET' && pathname.startsWith('/raw/') && !KV_RAW_PUBLIC){
    if(_kvBanned('rawkey', ip)){ _kvDenyText(res, 429, '-- ERROR: Too many invalid attempts.'); return false; }
    if(isRateLimited('kv-raw', ip, 40, 60 * 1000)){ _kvDenyText(res, 429, '-- ERROR: Rate limited.'); return false; }
    const isAdmin = _kvAdminOK(req);
    if(!isAdmin){
      const rk = String(req.headers['x-script-key'] || req.headers['x-app-key'] || url.searchParams.get('key') || '').trim();
      if(!(rk && sfVerifyKey(rk).valid)){
        _kvStrike('rawkey', ip, 12, 10 * 60 * 1000, 30 * 60 * 1000);
        _kvDenyText(res, 403, '-- ERROR: Key required or invalid/expired. Add ?key=YOUR_KEY');
        return false;
      }
      if(!KV_RAW_ALLOW_JS && _kvIsProtectedScript(pathname)){
        
        _kvDenyText(res, 404, '-- ERROR: File not found on server.');
        return false;
      }
    }
    return true;
  }

  
  if(method === 'GET' && pathname === '/api/public/code-bundle'){
    if(isRateLimited('kv-bundle', ip, 30, 60 * 1000)){ _kvDeny(res, 429, 'rate_limited', 'Gọi quá nhanh.'); return false; }
    const bk = String(req.headers['x-app-key'] || url.searchParams.get('key') || '').trim();
    if(_kvAdminOK(req) || (bk && sfVerifyKey(bk).valid)) return true;
    _kvDeny(res, 403, 'key_required', 'Cần key hợp lệ để kéo code.');
    return false;
  }

  
  if(method === 'GET' && (pathname === '/api/public/snippets' || pathname.startsWith('/api/public/snippet/'))){
    if(_kvBanned('enum', ip)){ _kvDeny(res, 429, 'too_many_requests', 'Thử lại sau.', { 'Retry-After': '900' }); return false; }
    if(_kvIsNavigation(req)){ _kvDeny(res, 404, 'not_found'); return false; } 
    
    if(!KV_SNIPPET_OPEN && !_kvAdminOK(req)){
      
      if(!_kvAntiScriptGuard(req, res, false)) return false;
      
      let rlId = kvTokenGate(req, ip);
      if(!rlId && KV_GATE_LEGACY){ 
        const sk = String(req.headers['x-script-key'] || req.headers['x-app-key'] || url.searchParams.get('key') || '').trim();
        if(sk && kvKeyGate(sk, ip).ok){ rlId = crypto.createHash('sha256').update(sk).digest('hex'); req._kvWmCtx = { k: _kvNormKey(sk), dev: '' }; }
      }
      if(!rlId){
        _kvStrike('enum', ip, 25, 10 * 60 * 1000, 15 * 60 * 1000);
        _kvDeny(res, 404, 'not_found'); 
        return false;
      }
      
      if(isRateLimited('kv-pub-bykey', rlId.slice(0, 16), 120, 60 * 1000)){ _kvDeny(res, 429, 'rate_limited', 'Gọi quá nhanh.'); return false; }
    }
    const pm = pathname.match(/^\/api\/public\/snippet\/([a-f0-9]+)(\/version)?$/);
    if(pm){
      if(isRateLimited(pm[2] ? 'kv-pub-ver' : 'kv-pub-code', ip, pm[2] ? 150 : 40, 60 * 1000)){
        _kvDeny(res, 429, 'rate_limited', 'Gọi quá nhanh.'); return false;
      }
      const sid = pm[1];
      const exists = (db.codeSnippets || []).some(s => s && s.id === sid) || !!_defaultSnippetMap[sid];
      if(!exists){
        _kvStrike('enum', ip, 25, 10 * 60 * 1000, 15 * 60 * 1000); 
        _kvDeny(res, 404, 'snippet_not_found'); return false;
      }
    } else if(isRateLimited('kv-pub-list', ip, 150, 60 * 1000)){
      _kvDeny(res, 429, 'rate_limited', 'Gọi quá nhanh.'); return false;
    }
    return true;
  }
  return true;
}
 

 
const _kvsNet = require('net');
const KVS_VERBOSE      = process.env.KV_PIPE_VERBOSE === '1';
const KVS_SECURE_ONLY  = process.env.KV_SECURE_ONLY === '1';
const KVS_LINK_TTL_MS  = Math.min(600000, Math.max(5000, parseInt(process.env.KV_LINK_TTL_MS, 10) || 45000));
const KVS_LINK_MAX_BYTES = 48 * 1024 * 1024;   
const KVS_LINK_MAX_ONE   = 16 * 1024 * 1024;   
const KVS_IP_FAIL_OPEN = process.env.KV_IP_FAIL_OPEN === '1';
const KVS_IP_BLOCK_HOSTING = process.env.KV_IP_BLOCK_HOSTING !== '0';
const KVS_IP_V4_PREFIX = Math.min(32, Math.max(8, parseInt(process.env.KV_IP_MATCH_V4_PREFIX, 10) || 24));
const KVS_IP_COUNTRIES = String(process.env.KV_IP_ALLOW_COUNTRIES || '').toUpperCase().split(',').map(s => s.trim()).filter(Boolean);
const KVS_IP_CHAIN   = String(process.env.KV_IPINTEL || 'ipapi_is,ip_api').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const KVS_IP_KEY     = String(process.env.KV_IPINTEL_KEY || '');
const KVS_IP_URL     = String(process.env.KV_IPINTEL_URL || '');
const KVS_IP_TTL     = 6 * 60 * 60 * 1000;     
const KVS_IP_TIMEOUT = 3500;
const KVS_IP_BUDGET  = parseInt(process.env.KV_IPINTEL_MAX_PER_MIN, 10) || 40;   
const KVS_IP_HEADERS = String(process.env.KV_IP_HEADER || (process.env.RENDER ? 'cf-connecting-ip,true-client-ip' : process.env.VERCEL ? 'x-vercel-forwarded-for,x-real-ip' : ''))
  .toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const KVS_IP_HOPS    = /^\d+$/.test(String(process.env.KV_IP_HOPS || '')) ? parseInt(process.env.KV_IP_HOPS, 10) : 0;

 
function kvsS(v, max){ 
  return String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f<>"'`&\\]/g, '').trim().slice(0, max || 100);
}
function kvsNormIP(raw){
  let s = String(raw == null ? '' : raw).trim();
  if(!s) return '';
  if(s[0] === '['){ const e = s.indexOf(']'); if(e > 0) s = s.slice(1, e); }
  else if(/^\d{1,3}(\.\d{1,3}){3}:\d+$/.test(s)) s = s.slice(0, s.lastIndexOf(':'));
  s = s.replace(/%.+$/, '').toLowerCase();
  const m = /^::ffff:(\d{1,3}(?:\.\d{1,3}){3})$/.exec(s);
  if(m) s = m[1];
  return _kvsNet.isIP(s) ? s : '';
}
function kvsExpandV6(ip){ // → mảng 8 nhóm số, hoặc null
  let s = String(ip);
  if(s.indexOf('.') >= 0){
    const i = s.lastIndexOf(':'), v = s.slice(i + 1).split('.').map(Number);
    if(v.length !== 4 || v.some(n => !(n >= 0 && n <= 255))) return null;
    s = s.slice(0, i + 1) + ((v[0] << 8) | v[1]).toString(16) + ':' + ((v[2] << 8) | v[3]).toString(16);
  }
  const parts = s.split('::');
  if(parts.length > 2) return null;
  const head = parts[0] ? parts[0].split(':') : [];
  const tail = parts.length === 2 && parts[1] ? parts[1].split(':') : [];
  const fill = parts.length === 2 ? 8 - head.length - tail.length : 0;
  if(fill < 0 || (parts.length === 1 && head.length !== 8)) return null;
  const g = head.concat(Array(fill).fill('0'), tail).map(x => parseInt(x, 16));
  return g.length === 8 && g.every(n => Number.isInteger(n) && n >= 0 && n <= 0xffff) ? g : null;
}
function kvsIsPublicIP(ip){
  const t = _kvsNet.isIP(ip);
  if(t === 4){
    const p = ip.split('.').map(Number), a = p[0], b = p[1], c = p[2];
    if(a === 0 || a === 10 || a === 127 || a >= 224) return false;
    if(a === 100 && b >= 64 && b <= 127) return false;           // CGNAT
    if(a === 169 && b === 254) return false;
    if(a === 172 && b >= 16 && b <= 31) return false;
    if(a === 192 && (b === 168 || (b === 0 && (c === 0 || c === 2)))) return false;
    if(a === 198 && (b === 18 || b === 19 || (b === 51 && c === 100))) return false;
    if(a === 203 && b === 0 && c === 113) return false;
    return true;
  }
  if(t === 6){
    const g = kvsExpandV6(ip);
    if(!g) return false;
    if((g[0] & 0xe000) !== 0x2000) return false;                   // chỉ global unicast 2000::/3
    if(g[0] === 0x2001 && g[1] === 0x0db8) return false;          // vùng tài liệu
    return true;
  }
  return false;
}
// true = cùng mạng (IPv4 theo KVS_IP_V4_PREFIX, IPv6 theo /64) · false = khác mạng · null = khác họ v4/v6, không so được
function kvsSameNet(a, b){
  const ta = _kvsNet.isIP(a), tb = _kvsNet.isIP(b);
  if(!ta || ta !== tb) return null;
  if(ta === 4){
    const pa = a.split('.').map(Number), pb = b.split('.').map(Number);
    let n = KVS_IP_V4_PREFIX;
    for(let i = 0; i < 4 && n > 0; i++){
      const take = Math.min(8, n), mask = (0xff << (8 - take)) & 0xff;
      if((pa[i] & mask) !== (pb[i] & mask)) return false;
      n -= take;
    }
    return true;
  }
  const ga = kvsExpandV6(a), gb = kvsExpandV6(b);
  if(!ga || !gb) return false;
  return ga[0] === gb[0] && ga[1] === gb[1] && ga[2] === gb[2] && ga[3] === gb[3];
}
/* IP thật của người gọi, KHÔNG tin X-Forwarded-For do client tự gửi (Render chỉ nối thêm vào header này,
   không xoá phần client gửi → phần tử đầu tiên giả được). Thứ tự tin cậy:
     (a) header do edge đặt (KV_IP_HEADER) — nếu đã cấu hình mà request không có header đó → coi như không tin được
     (b) KV_IP_HOPS = N: lấy phần tử thứ N tính từ PHẢI của chuỗi [X-Forwarded-For…, socket]
     (c) mặc định: địa chỉ socket (an toàn tuyệt đối, nhưng đứng sau proxy sẽ là IP nội bộ → bị từ chối)   */
function kvsClientIP(req){
  const h = req.headers || {};
  let found = '', via = '';
  for(const name of KVS_IP_HEADERS){
    const raw = h[name];
    if(!raw) continue;
    const ip = kvsNormIP(String(raw).split(',')[0]);
    if(!ip) return { ip: '', via: 'bad-header:' + name };                 // có header nhưng giá trị rác → không tin
    if(found && found !== ip) return { ip: '', via: 'header-conflict' };    // các header tin cậy mâu thuẫn nhau → có người giả
    if(!found){ found = ip; via = 'header:' + name; }
  }
  if(found) return { ip: found, via };
  if(KVS_IP_HEADERS.length) return { ip: '', via: 'missing-header' };
  const sock = kvsNormIP(req.socket && req.socket.remoteAddress);
  if(KVS_IP_HOPS <= 0) return { ip: sock, via: 'socket' };
  const chain = String(h['x-forwarded-for'] || '').split(',').map(kvsNormIP).concat([sock]);
  const idx = chain.length - 1 - KVS_IP_HOPS;
  return { ip: idx >= 0 ? chain[idx] : '', via: 'xff-hops:' + KVS_IP_HOPS };
}

