const KVX_OFF       = process.env.KV_KVX_OFF === '1' || String(process.env.KV_KVX_MODE || '').toLowerCase() === 'off';
const KVX_MODE      = String(process.env.KV_KVX_MODE || 'strict').toLowerCase() === 'compat' ? 'compat' : 'strict';   // [FIX-KVX] MẶC ĐỊNH strict: bỏ header X-KVX là bị từ chối (trước là compat → né KVX được). Cần cho loader cũ chạy tạm: KV_KVX_MODE=compat
