function kvxStrict(){ return !KVX_OFF && (KVX_MODE === 'strict' || (KVX_STRICT_AT > 0 && Date.now() >= KVX_STRICT_AT)); }
const KVX_POW_BITS  = (() => { const n = parseInt(process.env.KV_KVX_POW_BITS, 10); return Number.isFinite(n) ? Math.min(16, Math.max(0, n)) : 12; })();
const KVX_SESS_TTL_MS = 180 * 1000, KVX_SESS_MAX = 6000, KVX_SESS_PER_IP = 12, KVX_SESS_REQ_MAX = 8;
