const KVX_CSP_MODE    = String(process.env.KV_CSP || 'enforce').toLowerCase();          // enforce | report | off
const KVX_FORCE_HTTPS = process.env.KV_FORCE_HTTPS !== '0';
const KVX_HONEY_ON    = process.env.KV_HONEYPOT !== '0';
const KVX_AI_BLOCK_ON = process.env.KV_AI_BLOCK !== '0';
const KVX_MAX_CONN    = Math.max(100, parseInt(process.env.KV_MAX_CONN, 10) || 4000);
const KVX_ALLOWED_HOSTS = new Set(String(process.env.KV_ALLOWED_HOSTS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean));
const KVX_METHODS = new Set(['GET', 'HEAD', 'POST', 'PUT', 'DELETE', 'OPTIONS']);

