const _kvxStat = { since: Date.now(), hello: 0, helloDeny: 0, proofOk: 0, proofBad: 0, legacyOK: 0, legacyDeny: 0, sealed: 0, honeypot: 0, aiBlock: 0, edgeBlock: 0, sessBad: 0 };

/* ---- primitive ---- */
