  if(!KVX_METHODS.has(method)){ _kvxStat.edgeBlock++; kvxRaw(res, 405, null, { 'Allow': 'GET, HEAD, POST, PUT, DELETE, OPTIONS' }); return false; }
  if(String(req.url || '').length > 4096){ _kvxStat.edgeBlock++; kvxRaw(res, 414); return false; }
  const host = String(h.host || '');
  if(host.length > 255 || !/^[A-Za-z0-9.\-:\[\]]+$/.test(host)){ _kvxStat.edgeBlock++; kvxRaw(res, 400); return false; }
  if(KVX_ALLOWED_HOSTS.size){
    const hn = host.toLowerCase().replace(/:\d+$/, '');
    if(!KVX_ALLOWED_HOSTS.has(hn) && hn !== 'localhost' && hn !== '127.0.0.1'){ _kvxStat.edgeBlock++; kvxRaw(res, 421); return false; }
  }
