        const chk = crypto.createHash('md5').update(fileData).digest('hex');
        const entry = { id: crypto.randomBytes(10).toString('hex'), filename: safeN, diskFilename: diskFn, sizeBytes: fileData.length, checksum: chk, uploadedAt: new Date().toISOString() };
        db.androidJavaV2.files = (db.androidJavaV2.files || []).filter(f => f.filename !== safeN);
        db.androidJavaV2.files.push(entry);
        saveDBNow();
        console.log(`[AndroidJavaV2] Upload: ${diskFn} (${(fileData.length/1024).toFixed(1)} KB) id=${entry.id}`);
        const pubBase = resolvePublicUrl(req);
        return sendJSON(res, 200, { ok: true, id: entry.id, filename: entry.filename, diskFilename: diskFn, sizeBytes: entry.sizeBytes, checksum: chk, uploadedAt: entry.uploadedAt,
          rawUrl: pubBase ? `${pubBase}/raw/${encodeURIComponent(diskFn)}` : null,
          apiUrl: pubBase ? `${pubBase}/api/android/java-files-v2` : null });
